/* DOMiNANCE Breakdowns — reusable, accessible inline glossary.
 * Entry format: [title, definition, dontConfuse?, learnHref?, learnLabel?].
 * Hover or keyboard focus previews a card; a click or tap opens it as a small dialog
 * (a bottom sheet on phones) whose "Learn it fully" link opens the section that owns the term. */
(() => {
  'use strict';
  const terms = Object.freeze({
    'functional-syncytium': ['Functional syncytium', 'Heart muscle cells remain separate cells, but electrical signals pass between them so they contract together as one coordinated unit.', null, '#/physiology/cvs/cardiac-muscle?section=2-intercalated-discs-how-separate-cells-function-together', 'Cardiac Muscle §2'],
    'ecc': ['Excitation–contraction coupling (ECC)', 'How an electrical impulse makes heart muscle contract: it triggers a rise in calcium inside the cell, allowing the contractile proteins to work.', null, '#/physiology/cvs/cardiac-muscle?section=4-excitation-contraction-coupling-from-electrical-signal-to-force', 'Cardiac Muscle §4'],
    'cicr': ['Calcium-induced calcium release (CICR)', 'A small amount of calcium entering a heart cell opens RyR2 channels, releasing much more calcium from its internal store to strengthen contraction.', null, '#/physiology/cvs/cardiac-muscle?section=4-excitation-contraction-coupling-from-electrical-signal-to-force', 'Cardiac Muscle §4'],
    'serca': ['SERCA2a', 'A pump that uses ATP to return calcium to the heart cell’s internal store, allowing the muscle to relax.', null, '#/physiology/cvs/cardiac-muscle?section=5-how-does-cardiac-muscle-relax', 'Cardiac Muscle §5'],
    'ncx': ['Na⁺–Ca²⁺ exchanger (NCX)', 'A protein in the heart-cell membrane that usually moves calcium out of the cell by using the energy stored in the sodium gradient.', null, '#/physiology/cvs/cardiac-muscle?section=5-how-does-cardiac-muscle-relax', 'Cardiac Muscle §5'],
    'phospholamban': ['Phospholamban', 'A protein that normally slows the SERCA calcium pump. When phosphorylated, it releases this brake, so calcium is stored faster and the heart relaxes sooner.', null, '#/physiology/cvs/cardiac-muscle?section=7-how-do-the-sympathetic-and-vagal-nerves-change-cardiac-muscle', 'Cardiac Muscle §7'],
    'inotropy': ['Inotropy', 'How strongly heart muscle contracts at a given filling level. Positive inotropy means a stronger contraction without needing extra filling.', null, '#/physiology/cvs/cardiac-muscle?section=7-how-do-the-sympathetic-and-vagal-nerves-change-cardiac-muscle', 'Cardiac Muscle §7'],
    'lusitropy': ['Lusitropy', 'How quickly heart muscle relaxes after contracting. Faster relaxation helps the ventricles fill between beats.', null, '#/physiology/cvs/cardiac-muscle?section=7-how-do-the-sympathetic-and-vagal-nerves-change-cardiac-muscle', 'Cardiac Muscle §7'],
    'automaticity': ["Automaticity", "The ability of some heart cells to fire on their own, without a nerve signal. It is why the heart beats even when its nerves are cut.", "Heart rate control by the nerves, which only speed up or slow down this built-in rhythm.", "#/physiology/cvs/cardiac-conduction?section=3-why-is-the-sa-node-the-normal-pacemaker", "Cardiac Conduction §3"],
    'pacemaker-potential': ["Pacemaker potential", "The slow, automatic climb in a pacemaker cell's voltage between beats, until it reaches threshold and fires. Also called phase 4 or spontaneous diastolic depolarisation.", "The resting potential of a working muscle cell, which stays flat until a neighbour excites it.", "#/physiology/cvs/cardiac-conduction?section=3-why-is-the-sa-node-the-normal-pacemaker", "Cardiac Conduction §3"],
    'funny-current': ["Funny current (I_f)", "A leak of positive ions, mainly Na⁺, into SA node cells through HCN channels. It starts the slow climb to threshold. 'Funny' because the channels open when the cell becomes more negative.", null, "#/physiology/cvs/cardiac-conduction?section=3-why-is-the-sa-node-the-normal-pacemaker", "Cardiac Conduction §3"],
    'overdrive-suppression': ["Overdrive suppression", "When a slower pacemaker is repeatedly fired by a faster one, its own firing is temporarily suppressed. It explains the short pause before a backup pacemaker takes over.", null, "#/physiology/cvs/cardiac-conduction?section=4-if-other-conducting-cells-can-fire-spontaneously-why-doesn-t-each-set-its-own-rhythm", "Cardiac Conduction §4"],
    'dromotropy': ["Dromotropy", "An effect on how fast the electrical signal travels, especially through the AV node (dromo = running). Positive dromotropy means faster conduction and a shorter PR interval.", "Chronotropy, which is an effect on heart rate.", "#/physiology/cvs/cardiac-conduction?section=7-how-does-the-autonomic-nervous-system-influence-pacemaker-activity", "Cardiac Conduction §7"],
    'bruit': ["Bruit", "A whooshing sound heard over a blood vessel, made by turbulent flow: for example over a narrowed artery or an AV fistula.", "A murmur, the same kind of sound heard over the heart.", "#/physiology/cvs/heart-sounds?section=9-why-can-bruits-or-murmurs-arise-elsewhere", "Heart Sounds §9"],
    'ecg': ['Electrocardiogram (ECG)', 'A tracing of the heart’s electrical activity recorded from electrodes on the skin. It shows electrical activation and recovery, not the pumping force directly.', null, '#/physiology/cvs/ecg?section=1-what-does-an-ecg-actually-record', 'ECG §1'],
    'ecg-vector': ['Cardiac electrical vector', 'An arrow representing the overall strength and direction of the heart’s electrical activity at a moment. Each ECG lead records how much of that arrow points along its viewing direction.', null, '#/physiology/cvs/ecg?section=2-why-can-the-tracing-move-upwards-or-downwards', 'ECG §2'],
    'preload': ['Preload', 'How stretched the ventricular muscle is just before contraction. It depends mainly on ventricular filling; end-diastolic volume and pressure help estimate it.', null, '#/physiology/cvs/cardiac-output?section=3-what-determines-stroke-volume', 'Cardiac Output §3'],
    'afterload': ['Afterload', 'The force or load the ventricle must overcome to eject blood. It depends on arterial pressure and ventricular wall stress, not just vascular resistance.', null, '#/physiology/cvs/cardiac-output?section=3-what-determines-stroke-volume', 'Cardiac Output §3'],
    'chronotropy': ['Chronotropy', 'A change in heart rate. Positive chronotropy makes the heart beat faster; negative chronotropy slows it.', null, '#/physiology/cvs/cardiac-conduction?section=7-how-does-the-autonomic-nervous-system-influence-pacemaker-activity', 'Cardiac Conduction §7'],
    'systole-diastole': ["Systole and diastole", "Systole means contraction; diastole means relaxation. Always say which chambers: atrial systole and ventricular systole happen at different times.", "", "#/physiology/cvs/cardiac-cycle?section=1-one-heartbeat-what-the-atria-and-ventricles-are-doing", "Cardiac Cycle §1"],
    'sa-node': ["SA node (sinoatrial node)", "A small patch of pacemaker cells in the wall of the right atrium. It fires on its own and starts every normal heartbeat.", "", "#/physiology/cvs/cardiac-conduction?section=3-why-is-the-sa-node-the-normal-pacemaker", "Cardiac Conduction §3"],
    'av-node': ["AV node (atrioventricular node)", "The normal electrical gateway from the atria to the ventricles. It holds the impulse back briefly, so the atria finish contracting before the ventricles start.", "The AV valves, which are valves, not electrical tissue.", "#/physiology/cvs/cardiac-conduction?section=5-why-does-the-av-node-delay-electrical-conduction", "Cardiac Conduction §5"],
    'his-purkinje': ["His–Purkinje system", "Fast-conducting fibres that carry the impulse from the AV node through both ventricles, so the ventricular muscle is activated almost all at once.", "", "#/physiology/cvs/cardiac-conduction?section=6-why-is-ventricular-conduction-so-rapid", "Cardiac Conduction §6"],
    'av-valves': ["AV valves (atrioventricular valves)", "The valves between each atrium and its ventricle: the mitral valve on the left and the tricuspid valve on the right. They let blood into the ventricles.", "Semilunar valves, which let blood out of the ventricles.", "#/physiology/cvs/cardiac-cycle?section=2-the-one-rule-every-valve-follows", "Cardiac Cycle §2"],
    'semilunar-valves': ["Semilunar valves", "The valves between each ventricle and its artery: the aortic valve on the left and the pulmonary valve on the right. They let blood out of the ventricles.", "AV valves, which let blood into the ventricles.", "#/physiology/cvs/cardiac-cycle?section=2-the-one-rule-every-valve-follows", "Cardiac Cycle §2"],
    'papillary-muscles': ["Papillary muscles", "Small muscles in the ventricle wall, tied to the AV valve cusps by cords called chordae tendineae. They stop the cusps being pushed back into the atria.", "Valve openers. Valves open and shut by pressure alone.", "#/physiology/cvs/cardiac-cycle?section=2-the-one-rule-every-valve-follows", "Cardiac Cycle §2"],
    'atrial-kick': ["Atrial kick", "The final push of blood into the ventricles when the atria contract at the end of diastole. Most filling has already happened before it.", "The main source of filling, which is passive inflow.", "#/physiology/cvs/cardiac-cycle?section=3-filling-how-blood-enters-the-relaxed-ventricle", "Cardiac Cycle §3"],
    'diastasis': ["Diastasis", "The slow part of ventricular filling after the early rush. Atrial and ventricular pressures are now close, so blood only trickles in.", "", "#/physiology/cvs/cardiac-cycle?section=3-filling-how-blood-enters-the-relaxed-ventricle", "Cardiac Cycle §3"],
    'edv': ["EDV (end-diastolic volume)", "The blood in a ventricle at the end of filling, just before it contracts. About 130 mL in the lecture's example.", "Stroke volume, the part that is then ejected.", "#/physiology/cvs/cardiac-cycle?section=3-filling-how-blood-enters-the-relaxed-ventricle", "Cardiac Cycle §3"],
    'esv': ["ESV (end-systolic volume)", "The blood left in a ventricle after it finishes ejecting. A ventricle never empties completely.", "Stroke volume, the part that left.", "#/physiology/cvs/cardiac-cycle?section=5-ejection-why-blood-finally-leaves", "Cardiac Cycle §5"],
    'isovolumetric': ["Isovolumetric phase", "\"Iso\" means same, while \"volumetric\" refers to volume. It describes a period in the cardiac cycle when the inlet and outlet valves of each ventricle are closed, so no blood enters or leaves the ventricles. As a result, ventricular volume remains constant even though ventricular pressure changes.", "Ejection. It happens twice each beat, as isovolumetric contraction and isovolumetric relaxation, and blood only leaves once the outflow valves open: the aortic valve for the left ventricle and the pulmonary valve for the right.", "#/physiology/cvs/cardiac-cycle?section=4-isovolumetric-contraction-contracting-but-no-blood-leaves", "Cardiac Cycle §4"],
    'rapid-reduced-ejection': ["Rapid and reduced ejection", "Ejection starts fast, while the muscle is strong and the push is biggest (rapid). It then slows as the muscle weakens and the aorta fills (reduced).", "", "#/physiology/cvs/cardiac-cycle?section=5-ejection-why-blood-finally-leaves", "Cardiac Cycle §5"],
    's1': ["S1 (first heart sound)", "The \"lub\", heard as the mitral and tricuspid valves shut at the start of ventricular contraction.", "S2, heard when the aortic and pulmonary valves shut.", "#/physiology/cvs/heart-sounds?section=2-why-does-s1-occur-before-s2", "Heart Sounds §2"],
    's2': ["S2 (second heart sound)", "The \"dub\", heard as the aortic and pulmonary valves shut at the end of ejection.", "S1, heard when the mitral and tricuspid valves shut.", "#/physiology/cvs/heart-sounds?section=2-why-does-s1-occur-before-s2", "Heart Sounds §2"],
    'p-wave': ["P wave", "The ECG wave made as the impulse spreads across the atria. The atria contract just after it.", "The a wave, the pressure rise caused by that contraction.", "#/physiology/cvs/ecg?section=5-connect-the-ecg-to-mechanical-events", "Electrocardiography §5"],
    'qrs': ["QRS complex", "The tall ECG spike made as the impulse spreads through the ventricles. The ventricles contract just after it.", "S1, the sound that follows once the AV valves shut.", "#/physiology/cvs/ecg?section=5-connect-the-ecg-to-mechanical-events", "Electrocardiography §5"],
    't-wave': ["T wave", "The ECG wave made as the ventricles recover electrically (repolarise). It appears during late ejection; the muscle's force fades over the moments after.", "The end of ejection. Blood is still leaving during the T wave.", "#/physiology/cvs/ecg?section=5-connect-the-ecg-to-mechanical-events", "Electrocardiography §5"],
    'a-wave': ["a wave", "A small rise in atrial pressure caused by the atria contracting at the end of diastole.", "The P wave, the electrical signal that comes just before it.", "#/physiology/cvs/cardiac-cycle?section=9-reading-the-wiggers-diagram-one-trace-at-a-time", "Cardiac Cycle §9"],
    'c-wave': ["c wave", "A small bump in atrial pressure just as the ventricles start contracting. The rising ventricular pressure pushes the shut tricuspid and mitral valves so they bulge back into the atria. The atria themselves are not contracting.", "The a wave (the atria contracting) or the v wave (the atria filling up with blood).", "#/physiology/cvs/cardiac-cycle?section=4-isovolumetric-contraction-contracting-but-no-blood-leaves", "Cardiac Cycle §4"],
    'x-descent': ["x descent", "A dip in atrial pressure early in ejection. The atria are relaxing, and the contracting ventricles pull the AV valve ring down, making the atria bigger.", "The y descent, which happens when the AV valves open.", "#/physiology/cvs/cardiac-cycle?section=5-ejection-why-blood-finally-leaves", "Cardiac Cycle §5"],
    'v-wave': ["v wave", "A slow rise in atrial pressure while the AV valves are shut, as blood returning from the veins fills the atria. The atria are not contracting.", "The a wave, caused by the atria contracting.", "#/physiology/cvs/cardiac-cycle?section=6-closing-the-outflow-valves-and-isovolumetric-relaxation", "Cardiac Cycle §6"],
    'y-descent': ["y descent", "A drop in atrial pressure when the AV valves open and the blood stored in the atria rushes into the ventricles.", "The x descent, which happens while the AV valves are still shut.", "#/physiology/cvs/cardiac-cycle?section=6-closing-the-outflow-valves-and-isovolumetric-relaxation", "Cardiac Cycle §6"],
    'protodiastole': ["Protodiastole", "The brief moment at the end of ejection when forward flow stops and briefly reverses, pushing the aortic and pulmonary valves shut.", "", "#/physiology/cvs/cardiac-cycle?section=6-closing-the-outflow-valves-and-isovolumetric-relaxation", "Cardiac Cycle §6"],
    'dicrotic-notch': ["Dicrotic notch", "A small dip on the aortic pressure curve the moment the aortic valve snaps shut. For an instant blood moves backwards, causing the dip. Then the stretched aorta springs back against the closed valve, causing the small bump after it.", "A second heartbeat. The heart has not contracted again.", "#/physiology/cvs/cardiac-cycle?section=6-closing-the-outflow-valves-and-isovolumetric-relaxation", "Cardiac Cycle §6"],
    'stroke-volume': ["Stroke volume (SV)", "The blood one ventricle ejects in one beat: SV = EDV − ESV. About 70–90 mL in the lecture.", "EDV, what the ventricle holds before ejecting.", "#/physiology/cvs/cardiac-cycle?section=7-how-much-blood-does-the-ventricle-pump", "Cardiac Cycle §7"],
    'ejection-fraction': ["Ejection fraction (EF)", "The share of a ventricle's filled volume that it ejects each beat: EF = SV ÷ EDV × 100%. About 65% in the lecture.", "Stroke volume, which is a volume in mL, not a percentage.", "#/physiology/cvs/cardiac-cycle?section=7-how-much-blood-does-the-ventricle-pump", "Cardiac Cycle §7"],
    'wiggers': ["Wiggers diagram", "One chart that lines up the ECG, heart pressures, ventricular volume and heart sounds on the same timeline for one heartbeat.", "", "#/physiology/cvs/cardiac-cycle?section=9-reading-the-wiggers-diagram-one-trace-at-a-time", "Cardiac Cycle §9"],
    'pulmonary-impedance': ["Pulmonary impedance", "How much the lung blood vessels oppose blood flow. It falls when the lungs expand on inspiration, so blood keeps flowing into the pulmonary artery for longer.", "", "#/physiology/cvs/cardiac-cycle?section=10-right-versus-left-heart-s2-splitting-and-heart-rate", "Cardiac Cycle §10"],
    's2-splitting': ["Physiological splitting of S2", "S2 has two parts: A2 (aortic valve shutting) and P2 (pulmonary valve shutting). On inspiration, more blood returns to the right heart and the pulmonary vessels offer less opposition to flow, so right ventricular ejection lasts longer, P2 is delayed and the A2–P2 gap widens.", "A sign of disease. This widening on inspiration is normal.", "#/physiology/cvs/cardiac-cycle?section=10-right-versus-left-heart-s2-splitting-and-heart-rate", "Cardiac Cycle §10"],
    's3': ["S3 (third heart sound)", "A low sound just after S2, early in diastole, when the rush of blood filling the ventricle is suddenly slowed. Often normal in young people.", "S4, which comes just before S1 and needs the atria to contract.", "#/physiology/cvs/heart-sounds?section=4-what-causes-s3-and-s4", "Heart Sounds §4"],
    's4': ["S4 (fourth heart sound)", "A low sound just before S1, when the atria contract and push blood into a stiff ventricle. Absent in atrial fibrillation.", "S3, which comes just after S2, from rapid passive filling.", "#/physiology/cvs/heart-sounds?section=4-what-causes-s3-and-s4", "Heart Sounds §4"],
    'murmur': ["Murmur", "A whooshing sound heard over the heart, made by turbulent (swirling) blood flow. It lasts longer than the short thud of a heart sound.", "A heart sound (S1 to S4), which is a short thud.", "#/physiology/cvs/heart-sounds?section=6-what-makes-a-murmur", "Heart Sounds §6"],
    'laminar-flow': ["Laminar flow", "Normal, smooth blood flow: the blood moves in layers sliding past one another. It makes no sound.", "Turbulent flow, which swirls and can be heard.", "#/physiology/cvs/hemodynamics?section=5-laminar-flow-turbulence-and-reynolds-number", "Haemodynamics §5"],
    'turbulent-flow': ["Turbulent flow", "Blood flow that swirls and tumbles instead of moving in smooth layers. More likely when flow is fast, blood is thin or the channel narrows suddenly. It can be heard.", "Laminar flow, which is smooth and silent.", "#/physiology/cvs/hemodynamics?section=5-laminar-flow-turbulence-and-reynolds-number", "Haemodynamics §5"],
    'stenosis': ["Stenosis", "A narrowed valve that opens only partly. Blood is squeezed through as a fast forward jet, making a murmur while the valve should be open.", "Regurgitation, where the valve does not shut and blood leaks backwards.", "#/physiology/cvs/heart-sounds?section=7-predict-a-murmur-s-timing-without-memorising-a-list", "Heart Sounds §7"],
    'regurgitation': ["Regurgitation (incompetence)", "A valve that does not shut fully, so blood leaks backwards through it as a jet, making a murmur while the valve should be shut.", "Stenosis, where the valve does not open fully.", "#/physiology/cvs/heart-sounds?section=7-predict-a-murmur-s-timing-without-memorising-a-list", "Heart Sounds §7"],
    'flow-murmur': ["Flow murmur", "A murmur from fast or thin blood moving through normal valves, for example in anaemia, exercise, fever or pregnancy. It does not mean the valves are damaged.", "A murmur from a narrowed or leaking valve.", "#/physiology/cvs/heart-sounds?section=6-what-makes-a-murmur", "Heart Sounds §6"],
    'auscultation-areas': ["Auscultation areas", "The four chest spots where each valve is heard best: aortic (2nd right intercostal space), pulmonary (2nd left), tricuspid (lower left sternal border) and mitral (the apex).", "Where the valves actually sit: close together behind the sternum.", "#/physiology/cvs/heart-sounds?section=8-where-do-we-listen-to-each-heart-valve", "Heart Sounds §8"],
    'bulk-flow': ["Bulk flow", "Moving substances by carrying them along in a flowing fluid, the way blood carries oxygen, instead of letting them drift by diffusion. It is fast over long distances.", "Diffusion, which is fast only over a few micrometres.", "#/physiology/cvs/cv-introduction?section=1-why-do-we-need-a-circulatory-system", "Introduction §1"],
    'in-series': ["In series", "Arranged one after another, so everything that passes through the first must then pass through the second. The pulmonary and systemic circuits are in series.", "In parallel, where branches sit side by side.", "#/physiology/cvs/cv-introduction?section=2-the-two-major-circulatory-pathways", "Introduction §2"],
    'in-parallel': ["In parallel", "Arranged side by side, each with its own supply. The systemic organs are in parallel: each gets its own branch of fresh arterial blood.", "In series, where blood passes through one part and then the next.", "#/physiology/cvs/cv-introduction?section=2-the-two-major-circulatory-pathways", "Introduction §2"],
    'coronary-arteries': ["Coronary arteries", "The heart muscle's own arteries, branching from the aorta just above the aortic valve. The heart cannot feed itself from the blood inside its chambers.", null, "#/physiology/cvs/coronary?section=1-why-does-the-heart-need-a-separate-blood-supply", "Coronary Circulation §1"],
    'resistance': ["Resistance (to blood flow)", "How much the vessels oppose flow. The higher the resistance, the bigger the pressure difference needed for the same flow: flow = pressure difference ÷ resistance.", "Pressure, which is the push; resistance is what opposes it.", "#/physiology/cvs/hemodynamics?section=2-what-actually-determines-flow", "Haemodynamics §2"],
    'pulmonary-oedema': ["Pulmonary oedema", "Fluid that has leaked out of the lung capillaries into the lung tissue and air spaces. It makes gas exchange harder.", null, "#/physiology/cvs/cv-introduction?section=4-why-is-the-left-ventricular-wall-thicker-than-the-right", "Introduction §4"],
    'sarcomere': ["Sarcomere", "The repeating unit of a muscle fibre, made of overlapping actin and myosin filaments. Sarcomeres shorten when the muscle contracts.", null, "#/physiology/cvs/cardiac-muscle?section=1-what-makes-cardiac-muscle-different", "Cardiac Muscle §1"],
    'refractory-period': ["Refractory period", "The time after an action potential when a heart cell cannot fire again. In heart muscle it lasts almost as long as the contraction, so beats cannot merge into tetanus.", "The plateau, the flat part of the action potential that causes most of this delay.", "#/physiology/cvs/cardiac-muscle?section=6-why-can-t-cardiac-muscle-undergo-normal-tetanus", "Cardiac Muscle §6"],
    't-tubules': ["T-tubules", "Tubes of surface membrane that dive deep into a muscle cell, carrying the electrical signal close to the cell's calcium store.", "The sarcoplasmic reticulum, the calcium store inside the cell.", "#/physiology/cvs/cardiac-muscle?section=4-excitation-contraction-coupling-from-electrical-signal-to-force", "Cardiac Muscle §4"],
    'sarcoplasmic-reticulum': ["Sarcoplasmic reticulum (SR)", "The muscle cell's internal calcium store. It releases calcium to start contraction and takes it back so the muscle can relax.", "T-tubules, which carry the electrical signal into the cell.", "#/physiology/cvs/cardiac-muscle?section=4-excitation-contraction-coupling-from-electrical-signal-to-force", "Cardiac Muscle §4"],
    'xanthines': ["Xanthines", "Drugs such as caffeine and theophylline. They block phosphodiesterase, the enzyme that breaks down cAMP, so cAMP builds up and heart muscle contracts more strongly.", null, "#/physiology/cvs/cardiac-muscle?section=7-how-do-the-sympathetic-and-vagal-nerves-change-cardiac-muscle", "Cardiac Muscle §7"],
    'escape-rhythm': ["Escape rhythm", "A slower backup rhythm from the AV junction (about 40–60/min) or the ventricles (about 20–40/min) that takes over when the SA node's signal stops reaching them.", null, "#/physiology/cvs/cardiac-conduction?section=4-if-other-conducting-cells-can-fire-spontaneously-why-doesn-t-each-set-its-own-rhythm", "Cardiac Conduction §4"],
    'vagal-tone': ["Vagal tone", "The constant braking of the heart by the vagus nerve at rest. It holds the SA node below its own rate of about 100/min; blocking it with atropine raises the heart rate.", null, "#/physiology/cvs/cardiac-conduction?section=7-how-does-the-autonomic-nervous-system-influence-pacemaker-activity", "Cardiac Conduction §7"],
    'einthoven': ["Einthoven's triangle", "The triangle formed by Leads I, II and III around the heart, using the right arm, left arm and left leg electrodes. Because they share electrodes, Lead II = Lead I + Lead III at any instant.", null, "#/physiology/cvs/ecg?section=3-why-can-ten-electrodes-produce-twelve-ecg-leads", "Electrocardiography §3"],
    'unipolar-lead': ["Unipolar lead", "A lead with one electrode as its positive end, compared with an average of other electrodes rather than a single partner. aVR, aVL, aVF and V1–V6 are unipolar.", "Bipolar leads (I, II, III), which compare two single limb electrodes.", "#/physiology/cvs/ecg?section=3-why-can-ten-electrodes-produce-twelve-ecg-leads", "Electrocardiography §3"],
    'j-point': ["J point", "The point where the QRS complex ends and the ST segment begins.", null, "#/physiology/cvs/ecg?section=4-waves-segments-and-intervals-what-is-the-difference", "Electrocardiography §4"],
    'qt-interval': ["QT interval", "From the start of the QRS to the end of the T wave: the ventricles switching on and resetting. About 0.2–0.4 s, shorter at faster heart rates.", null, "#/physiology/cvs/ecg?section=4-waves-segments-and-intervals-what-is-the-difference", "Electrocardiography §4"],
    'rr-interval': ["RR interval", "The time between two R waves: the length of one heartbeat. Heart rate = 60 ÷ RR (in seconds).", null, "#/physiology/cvs/ecg?section=7-calculate-heart-rate-from-the-tracing", "Electrocardiography §7"],
    'heterometric': ["Heterometric regulation", "hetero = different, metric = length. The heart changes its output because its starting fibre length changed: the Frank–Starling mechanism.", "Homometric regulation, which changes force at the same length.", "#/physiology/cvs/cardiac-output?section=5-how-do-we-read-frank-starling-curves", "Cardiac Output §5"],
    'homometric': ["Homometric regulation", "homo = same. The heart changes its force at the same starting length, for example when sympathetic stimulation raises contractility.", "Heterometric regulation (Frank–Starling), which works by changing the starting length.", "#/physiology/cvs/cardiac-output?section=5-how-do-we-read-frank-starling-curves", "Cardiac Output §5"],
    'cardiac-index': ["Cardiac index", "Cardiac output divided by body surface area (L/min/m²), so people of different sizes can be compared. About 3 L/min/m² at rest.", null, "#/physiology/cvs/cardiac-output?section=1-what-is-cardiac-output-and-why-does-it-matter", "Cardiac Output §1"],
    'fick': ["Fick's principle", "Oxygen used by the body per minute = blood flow × oxygen dropped off by each mL of blood. So cardiac output = O₂ use ÷ (arterial − mixed venous O₂ content).", null, "#/physiology/cvs/co-measurement?section=2-fick-s-principle-working-out-flow-from-oxygen-use", "Measuring Cardiac Output §2"],
    'mixed-venous': ["Mixed venous blood", "Venous blood from the whole body after it has mixed in the right heart, sampled from the pulmonary artery before it reaches the lungs.", "Blood from one peripheral vein, which shows only what that region used.", "#/physiology/cvs/co-measurement?section=3-where-do-the-oxygen-measurements-come-from", "Measuring Cardiac Output §3"],
    'o2-saturation': ["Oxygen saturation", "The percentage of haemoglobin carrying oxygen. It is not the amount of oxygen in the blood: with little haemoglobin, saturation can be normal while content is low.", "Oxygen content, the actual mL of O₂ in each mL of blood.", "#/physiology/cvs/co-measurement?section=2-fick-s-principle-working-out-flow-from-oxygen-use", "Measuring Cardiac Output §2"],
    'thermodilution': ["Thermodilution", "Measuring cardiac output by injecting cold saline through a pulmonary artery catheter and recording how the blood temperature changes downstream. Faster flow gives a smaller, shorter dip.", null, "#/physiology/cvs/co-measurement?section=4-other-ways-to-measure-flow-indicator-dilution-supplementary", "Measuring Cardiac Output §4"],
    'stroke-work': ["Stroke work", "The work done by the ventricle in one beat to push blood against pressure: about stroke volume × pressure, or exactly the area inside the pressure–volume loop.", "The heart's total oxygen use, which also includes calcium pumping and other costs.", "#/physiology/cvs/co-measurement?section=5-what-does-it-mean-for-the-heart-to-perform-work", "Measuring Cardiac Output §5"],
    'wall-tension': ["Wall tension (wall stress)", "The force stretched across the ventricular wall. It rises with the pressure inside and the size of the chamber, and is the biggest driver of the heart muscle's oxygen use.", null, "#/physiology/cvs/co-measurement?section=7-why-does-pressure-loading-increase-the-heart-s-oxygen-demand", "Measuring Cardiac Output §7"],
    'venous-valves': ["Venous valves", "Flaps inside many veins, especially in the legs, that let blood flow only towards the heart. When muscles squeeze the veins, the valves stop blood being pushed backwards.", null, "#/physiology/cvs/hemodynamics?section=1-what-propels-blood-around-the-circulation", "Haemodynamics §1"],
    'reynolds': ["Reynolds number (Re)", "A number with no units that predicts how likely flow is to become turbulent: Re = density × velocity × diameter ÷ viscosity. Higher Re, more likely turbulence.", "Resistance (R), which is a different quantity.", "#/physiology/cvs/hemodynamics?section=5-laminar-flow-turbulence-and-reynolds-number", "Haemodynamics §5"],
    'poiseuille': ["Poiseuille's equation", "Describes smooth flow through a tube. Its key message: resistance depends on radius to the fourth power, so halving the radius raises resistance 16-fold.", null, "#/physiology/cvs/hemodynamics?section=6-why-is-vessel-radius-such-a-powerful-determinant-of-flow", "Haemodynamics §6"],
    'haematocrit': ["Haematocrit", "The percentage of blood volume made up of red cells (about 40–45%). A higher haematocrit makes blood thicker (more viscous).", null, "#/physiology/cvs/hemodynamics?section=7-viscosity-haematocrit-and-blood-cells", "Haemodynamics §7"],
    'compliance': ["Compliance", "How much a vessel's volume rises for each rise in pressure (C = ΔV ÷ ΔP). Veins are very compliant, so they store most of the blood.", "Resistance, which is about how hard it is for blood to flow through.", "#/physiology/cvs/hemodynamics?section=10-why-can-veins-hold-more-blood-than-arteries", "Haemodynamics §10"],
    'windkessel': ["Windkessel effect", "The aorta stretches as blood is ejected and springs back between beats, pushing blood onwards. It turns the heart's spurts into steadier flow.", null, "#/physiology/cvs/blood-pressure?section=2-why-doesn-t-blood-stop-moving-during-diastole", "Blood Pressure §2"],
    'svr': ["Systemic vascular resistance (SVR)", "The total resistance of all the body's vessels (outside the lungs), set mainly by the arterioles. MAP ≈ cardiac output × SVR.", null, "#/physiology/cvs/blood-pressure?section=3-why-do-systolic-and-diastolic-pressure-depend-on-more-than-heart-rate", "Blood Pressure §3"],
    'map': ["Mean arterial pressure (MAP)", "The average arterial pressure over a whole beat, about diastolic + one-third of the pulse pressure. It is the pressure that drives blood into the tissues.", "The midpoint between systolic and diastolic, which is higher.", "#/physiology/cvs/blood-pressure?section=5-what-is-mean-arterial-pressure-and-why-isn-t-it-simply-the-midpoint", "Blood Pressure §5"],
    'korotkoff': ["Korotkoff sounds", "Taps heard over the brachial artery below a deflating cuff, made by blood spurting through the squeezed artery. First tap = systolic; disappearance = diastolic.", "Heart sounds (S1, S2), which come from the heart valves.", "#/physiology/cvs/blood-pressure?section=7-how-does-a-cuff-and-stethoscope-reveal-systolic-and-diastolic-pressure", "Blood Pressure §7"],
    'auscultatory-gap': ["Auscultatory gap", "A silent stretch between systolic and diastolic in some people, when the Korotkoff taps fade and return. Feeling the pulse first stops you mistaking it for the start.", null, "#/physiology/cvs/blood-pressure?section=8-how-should-bp-actually-be-measured-accurately", "Blood Pressure §8"],
    'oscillometric': ["Oscillometric monitor", "An automatic BP machine. It senses small pressure wobbles in the cuff as the artery pulses, and calculates the BP instead of listening for sounds.", null, "#/physiology/cvs/blood-pressure?section=8-how-should-bp-actually-be-measured-accurately", "Blood Pressure §8"],
    'venous-return': ["Venous return", "The volume of blood flowing back into the right atrium each minute. Over time it equals cardiac output.", null, "#/physiology/cvs/venous-return?section=1-what-is-venous-return-and-why-is-it-essential", "Venous Return §1"],
    'venoconstriction': ["Venoconstriction", "Tightening of the smooth muscle in vein walls by sympathetic nerves. The veins hold less, so stored blood is pushed back to the heart.", "Arteriolar constriction, which mainly raises resistance and cuts flow to organs.", "#/physiology/cvs/venous-return?section=2-why-are-veins-called-capacitance-vessels", "Venous Return §2"],
    'pmsf': ["Mean systemic filling pressure", "How full the circulation is: the pressure everywhere if the heart stopped and pressures evened out. It rises with more blood volume or tighter veins, and drives venous return.", "Central venous pressure, measured next to the right atrium.", "#/physiology/cvs/venous-return?section=3-what-pressure-actually-drives-venous-return", "Venous Return §3"],
    'cvp': ["Central venous pressure (CVP)", "Pressure in the large veins beside the right atrium, a few mmHg. High CVP can mean fluid overload or a failing right ventricle.", "Blood volume, which CVP does not measure directly.", "#/physiology/cvs/venous-return?section=6-what-does-central-venous-pressure-tell-us", "Venous Return §6"],
    'dural-sinus': ["Dural venous sinuses", "Venous channels inside the skull, held open by tough dura, so they can't collapse when their pressure falls below atmospheric.", null, "#/physiology/cvs/venous-return?section=7-what-happens-to-veins-in-the-head-when-standing", "Venous Return §7"],
    'air-embolism': ["Air embolism", "Air bubbles entering the circulation, for example sucked into an open vein with below-atmospheric pressure. They can block blood flow in the heart or lungs.", null, "#/physiology/cvs/venous-return?section=7-what-happens-to-veins-in-the-head-when-standing", "Venous Return §7"],
    'microcirculation': ["Microcirculation", "The smallest vessels in a tissue: arterioles, capillaries and venules, where blood exchanges with the cells.", null, "#/physiology/cvs/microcirculation?section=1-why-is-the-microcirculation-necessary", "Microcirculation §1"],
    'pericytes': ["Pericytes", "Cells wrapped around the outside of capillaries that support and stabilise the capillary wall.", null, "#/physiology/cvs/microcirculation?section=2-what-is-a-capillary-wall-made-of", "Microcirculation §2"],
    'fenestrated': ["Fenestrated capillary", "A capillary whose endothelial cells have tiny pores (fenestra = window), letting water and small solutes cross quickly. Found in the gut, glands and kidney.", "Sinusoidal capillaries, which have much larger gaps.", "#/physiology/cvs/microcirculation?section=2-what-is-a-capillary-wall-made-of", "Microcirculation §2"],
    'precapillary-sphincter': ["Precapillary sphincter", "A ring of smooth muscle at the entrance to a capillary that can open or close it. Classic teaching; not every capillary has one.", null, "#/physiology/cvs/microcirculation?section=4-what-decides-which-capillaries-receive-more-blood", "Microcirculation §4"],
    'hydrostatic-pressure': ["Hydrostatic pressure", "The push of a fluid against its container. In a capillary, blood pressure (Pc) pushes water out.", "Oncotic pressure, the pull of proteins.", "#/physiology/cvs/microcirculation?section=5-why-does-fluid-leave-capillaries-even-when-protein-stays-in-blood", "Microcirculation §5"],
    'oncotic-pressure': ["Oncotic pressure", "The pull of proteins that can't cross the capillary wall. Plasma albumin pulls water into the blood (πc).", "Hydrostatic pressure, the push of the fluid itself.", "#/physiology/cvs/microcirculation?section=5-why-does-fluid-leave-capillaries-even-when-protein-stays-in-blood", "Microcirculation §5"],
    'glycocalyx': ["Endothelial glycocalyx", "A gel-like layer coating the inside of capillaries. It keeps the protein pull strong along the capillary, so little fluid is reabsorbed and the lymph returns most of it.", null, "#/physiology/cvs/microcirculation?section=6-classic-starling-model-versus-revised-understanding", "Microcirculation §6"],
    'oedema': ["Oedema", "Too much fluid in the spaces between cells: more leaves the capillaries than the lymphatics can carry away.", null, "#/physiology/cvs/edema?section=1-what-exactly-is-oedema", "Oedema §1"],
    'kf': ["Filtration coefficient (Kf)", "How leaky the capillary wall is, together with how much wall area there is. Inflammation raises it.", null, "#/physiology/cvs/edema?section=2-what-physical-forces-govern-filtration", "Oedema §2"],
    'reflection-coefficient': ["Reflection coefficient (σ)", "How well the capillary wall holds back protein: 1 = none crosses, 0 = all crosses. It falls in leaky, inflamed capillaries, so the protein pull is lost.", null, "#/physiology/cvs/edema?section=2-what-physical-forces-govern-filtration", "Oedema §2"],
    'nephrotic': ["Nephrotic syndrome", "A kidney disorder in which large amounts of protein leak into the urine, so plasma albumin falls and oedema develops.", null, "#/physiology/cvs/edema?section=5-why-can-low-plasma-proteins-cause-oedema", "Oedema §5"],
    'lymphoedema': ["Lymphoedema", "Swelling caused by blocked or missing lymphatics. Protein-rich fluid builds up and, over time, the tissue becomes firm and scarred.", null, "#/physiology/cvs/edema?section=7-why-does-lymphatic-obstruction-cause-persistent-swelling", "Oedema §7"],
    'pitting': ["Pitting oedema", "Swelling where firm thumb pressure leaves a dent, because the extra fluid is free to move. Typical of heart failure, low albumin and venous causes.", "Non-pitting oedema, where scarred tissue resists the dent.", "#/physiology/cvs/edema?section=8-why-are-pitting-and-non-pitting-oedema-different", "Oedema §8"],
    'lymphatic-system': ["Lymphatic system", "A one-way network of vessels and nodes that collects excess tissue fluid and protein and returns them to the veins at the base of the neck.", null, "#/physiology/cvs/lymphatics?section=1-why-do-we-need-lymphatic-vessels-if-we-already-have-veins", "Lymphatics §1"],
    'anchoring-filaments': ["Anchoring filaments", "Fine strands tying lymph capillary cells to the surrounding tissue. When tissue swells they pull the overlapping flaps open, letting fluid in.", null, "#/physiology/cvs/lymphatics?section=2-how-does-lymph-enter-a-lymphatic-capillary", "Lymphatics §2"],
    'venous-angle': ["Venous angle", "The junction of the internal jugular and subclavian veins at the base of the neck, where the main lymph ducts empty into the blood.", null, "#/physiology/cvs/lymphatics?section=4-where-does-lymph-finally-return-to-blood", "Lymphatics §4"],
    'lacteal': ["Lacteal", "The lymph capillary inside each intestinal villus. It takes up chylomicrons (absorbed long-chain fats), which are too big for blood capillaries.", null, "#/physiology/cvs/lymphatics?section=5-why-is-the-intestinal-lymphatic-system-important-in-fat-absorption", "Lymphatics §5"],
    'chylomicron': ["Chylomicron", "A large droplet of absorbed dietary fat wrapped in protein, made by gut cells and carried away in the lymph.", null, "#/physiology/cvs/lymphatics?section=5-why-is-the-intestinal-lymphatic-system-important-in-fat-absorption", "Lymphatics §5"],
    'chyle': ["Chyle", "Milky, fat-rich lymph from the intestine after a meal, full of chylomicrons.", null, "#/physiology/cvs/lymphatics?section=5-why-is-the-intestinal-lymphatic-system-important-in-fat-absorption", "Lymphatics §5"],
    'elephantiasis': ["Elephantiasis", "Gross, thickened swelling of a limb or the scrotum from long-standing lymphatic blockage, usually by filarial worms.", null, "#/physiology/cvs/lymphatics?section=7-why-does-lymphatic-obstruction-cause-lymphoedema", "Lymphatics §7"],
    'heart-failure': ["Heart failure", "The heart can't pump enough blood for the body's needs, or can only do so at abnormally high filling pressures.", null, "#/physiology/cvs/heart-failure?section=1-what-is-heart-failure", "Heart Failure §1"],
    'forward-failure': ["Forward failure", "Too little blood pumped out, so organs are underperfused: tiredness, poor exercise tolerance, salt and water retention.", "Backward failure, which is congestion behind the failing chamber.", "#/physiology/cvs/heart-failure?section=1-what-is-heart-failure", "Heart Failure §1"],
    'backward-failure': ["Backward failure", "Blood backs up behind a failing chamber, congesting the veins upstream: the lungs for the left side, the body for the right.", "Forward failure, which is too little output.", "#/physiology/cvs/heart-failure?section=1-what-is-heart-failure", "Heart Failure §1"],
    'orthopnoea': ["Orthopnoea", "Breathlessness when lying flat, relieved by sitting up. Lying down returns pooled blood to the chest, which a failing left ventricle cannot handle.", null, "#/physiology/cvs/heart-failure?section=3-left-versus-right-failure-where-does-the-blood-back-up", "Heart Failure §3"],
    'ascites': ["Ascites", "Fluid collecting in the abdominal cavity, for example from high venous pressure in right heart failure or liver disease.", null, "#/physiology/cvs/heart-failure?section=3-left-versus-right-failure-where-does-the-blood-back-up", "Heart Failure §3"],
    'remodelling': ["Ventricular remodelling", "Long-term changes in the shape and size of a failing ventricle (dilating or thickening) that make it pump less efficiently.", null, "#/physiology/cvs/heart-failure?section=4-what-does-the-body-do-about-it-and-why-does-that-make-it-worse", "Heart Failure §4"],
    'aortic-sinuses': ["Aortic sinuses", "Small pouches in the aortic wall just above the aortic valve cusps. The right and left coronary arteries arise from them.", null, "#/physiology/cvs/coronary?section=1-why-does-the-heart-need-a-separate-blood-supply", "Coronary §1"],
    'coronary-dominance': ["Coronary dominance", "Which artery gives off the posterior descending artery: usually the right coronary artery (right dominant).", null, "#/physiology/cvs/coronary?section=2-trace-coronary-inflow-and-venous-drainage", "Coronary §2"],
    'coronary-sinus': ["Coronary sinus", "The large vein on the back of the heart that collects most coronary venous blood and empties into the right atrium.", null, "#/physiology/cvs/coronary?section=2-trace-coronary-inflow-and-venous-drainage", "Coronary §2"],
    'subendocardium': ["Subendocardium", "The inner layer of the ventricular wall, squeezed hardest in systole, so it is the first to become ischaemic.", null, "#/physiology/cvs/coronary?section=3-why-is-left-ventricular-coronary-perfusion-greatest-during-diastole", "Coronary §3"],
    'adenosine': ["Adenosine", "A breakdown product of ATP released by working or oxygen-starved heart muscle. It dilates coronary arterioles, matching flow to work.", null, "#/physiology/cvs/coronary?section=4-how-does-coronary-flow-match-changing-myocardial-work", "Coronary §4"],
    'active-hyperaemia': ["Active hyperaemia", "A rise in blood flow to a tissue because it is working harder, driven by local metabolites that dilate its arterioles.", "Reactive hyperaemia, the extra flow after a blockage is released.", "#/physiology/cvs/coronary?section=4-how-does-coronary-flow-match-changing-myocardial-work", "Coronary §4"],
    'flow-reserve': ["Coronary flow reserve", "How much coronary flow can rise above resting when the arterioles fully dilate, normally about 4 to 5 times. A narrowed artery uses it up.", null, "#/physiology/cvs/coronary?section=6-coronary-flow-reserve-angina-and-myocardial-infarction", "Coronary §6"],
    'angina': ["Angina", "Chest pain from temporary myocardial ischaemia: oxygen supply falls short of demand. It is reversible, unlike infarction.", "Myocardial infarction, where heart muscle dies.", "#/physiology/cvs/coronary?section=6-coronary-flow-reserve-angina-and-myocardial-infarction", "Coronary §6"],
    'placenta': ["Placenta", "The organ where fetal and maternal blood come close enough to exchange gases and nutrients. It does the fetus's gas exchange, not the lungs.", "The umbilical cord, which only carries blood to and from it.", "#/physiology/cvs/fetal?section=1-why-does-the-fetus-need-shortcuts", "Fetal Circulation §1"],
    'ductus-venosus': ["Ductus venosus", "A fetal vessel that carries umbilical venous blood past the liver, straight into the inferior vena cava.", "The ductus arteriosus, which bypasses the lungs.", "#/physiology/cvs/fetal?section=2-trace-the-fetal-circuit", "Fetal Circulation §2"],
    'foramen-ovale': ["Foramen ovale", "An opening in the fetal atrial septum. Oxygen-rich blood crosses from the right atrium to the left atrium through it.", "The fossa ovalis, the shallow dip it leaves after closing.", "#/physiology/cvs/fetal?section=2-trace-the-fetal-circuit", "Fetal Circulation §2"],
    'ductus-arteriosus': ["Ductus arteriosus", "A fetal vessel linking the pulmonary trunk to the descending aorta, so most right ventricular output bypasses the lungs.", "The ductus venosus, which bypasses the liver.", "#/physiology/cvs/fetal?section=2-trace-the-fetal-circuit", "Fetal Circulation §2"],
    'fetal-haemoglobin': ["Fetal haemoglobin (HbF)", "The haemoglobin of the fetus. It binds 2,3-BPG less strongly, so it holds oxygen more tightly than adult haemoglobin and can take oxygen from maternal blood.", null, "#/physiology/cvs/fetal?section=3-fetal-haemoglobin-grabbing-oxygen-from-the-mother", "Fetal Circulation §3"],
    'bpg': ["2,3-BPG", "A molecule in red cells that loosens haemoglobin's grip on oxygen. Fetal haemoglobin binds it weakly.", null, "#/physiology/cvs/fetal?section=3-fetal-haemoglobin-grabbing-oxygen-from-the-mother", "Fetal Circulation §3"],
    'fossa-ovalis': ["Fossa ovalis", "The shallow dip in the adult atrial septum where the foramen ovale used to be.", "The foramen ovale, the open fetal channel.", "#/physiology/cvs/fetal?section=4-what-closes-after-delivery", "Fetal Circulation §4"],
    'ligamentum-arteriosum': ["Ligamentum arteriosum", "The fibrous cord left when the ductus arteriosus closes, joining the pulmonary trunk to the aorta.", "The ligamentum venosum, the remnant of the ductus venosus.", "#/physiology/cvs/fetal?section=4-what-closes-after-delivery", "Fetal Circulation §4"],
    'coeliac-trunk': ["Coeliac trunk", "The first unpaired branch of the abdominal aorta. It supplies the stomach, liver, spleen and upper duodenum.", "The superior mesenteric artery, which supplies most of the small intestine.", "#/physiology/cvs/splanchnic?section=1-an-unusual-route-through-two-capillary-beds", "Splanchnic Circulation §1"],
    'portal-vein': ["Portal vein", "The vein that carries blood from the gut and spleen to the liver, so it passes a second capillary bed before reaching the heart.", "The hepatic veins, which drain the liver into the inferior vena cava.", "#/physiology/cvs/splanchnic?section=1-an-unusual-route-through-two-capillary-beds", "Splanchnic Circulation §1"],
    'sinusoid': ["Sinusoid", "A wide, very leaky capillary. In the liver, portal and arterial blood mix in the sinusoids as they flow towards the central vein.", "An ordinary continuous capillary, which leaks far less.", "#/physiology/cvs/splanchnic?section=2-the-liver-s-double-blood-supply-and-its-zones", "Splanchnic Circulation §2"],
    'portal-triad': ["Portal triad", "The group of three channels at the edge of a liver lobule: a portal vein branch, a hepatic artery branch and a bile duct.", "The central vein, at the other end of the sinusoids.", "#/physiology/cvs/splanchnic?section=2-the-liver-s-double-blood-supply-and-its-zones", "Splanchnic Circulation §2"],
    'hepatic-zones': ["Liver zones", "Zone 1 lies near the portal triad and gets the most oxygen. Zone 3 lies near the central vein and gets the least, so it is damaged first when flow falls.", null, "#/physiology/cvs/splanchnic?section=2-the-liver-s-double-blood-supply-and-its-zones", "Splanchnic Circulation §2"],
    'space-of-disse': ["Space of Disse", "The narrow gap between the sinusoid lining and the liver cells, where plasma touches the cells. Fluid here drains as hepatic lymph.", null, "#/physiology/cvs/splanchnic?section=2-the-liver-s-double-blood-supply-and-its-zones", "Splanchnic Circulation §2"],
    'postprandial-hyperaemia': ["Postprandial hyperaemia", "The rise in gut blood flow after a meal, as the working gut dilates its arterioles.", null, "#/physiology/cvs/splanchnic?section=3-blood-flow-after-meals-and-in-shock", "Splanchnic Circulation §3"],
    'cirrhosis': ["Cirrhosis", "Scarring of the liver that obstructs blood flow through it, raising portal pressure.", null, "#/physiology/cvs/splanchnic?section=4-why-does-fluid-collect-as-ascites", "Splanchnic Circulation §4"],
    'ava': ["Arteriovenous anastomosis (AVA)", "A direct shortcut from a small artery to a vein, mainly in the fingers, toes, ears and nose. When open, it sends warm blood under the skin to lose heat.", "A capillary, where exchange happens. AVAs are for heat, not exchange.", "#/physiology/cvs/skin?section=1-skin-blood-flow-is-mainly-about-heat-not-nutrition", "Skin Circulation §1"],
    'flare': ["Flare", "The spreading, blotchy redness around a firm skin stroke. It is caused by the axon reflex.", "The red line, which stays exactly along the stroke.", "#/physiology/cvs/skin?section=3-the-triple-response-of-lewis", "Skin Circulation §3"],
    'axon-reflex': ["Axon reflex", "A response that runs within the branches of one sensory nerve fibre: an impulse from one branch travels back down the others, whose endings release vasodilators. No spinal cord is needed.", "A true reflex arc, which passes through the spinal cord.", "#/physiology/cvs/skin?section=3-the-triple-response-of-lewis", "Skin Circulation §3"],
    'wheal': ["Wheal", "A raised, pale swelling along a firm skin stroke. Histamine makes the capillaries leaky, so fluid leaks into the tissue.", "The flare, which is redness without swelling.", "#/physiology/cvs/skin?section=3-the-triple-response-of-lewis", "Skin Circulation §3"],
    'substance-p': ["Substance P", "A peptide released from sensory nerve endings. It dilates arterioles and makes mast cells release histamine.", null, "#/physiology/cvs/skin?section=3-the-triple-response-of-lewis", "Skin Circulation §3"],
    'cgrp': ["CGRP", "Calcitonin gene-related peptide: a strong vasodilator released from sensory nerve endings, for example in the axon reflex.", null, "#/physiology/cvs/skin?section=3-the-triple-response-of-lewis", "Skin Circulation §3"],
    'mast-cell': ["Mast cell", "A tissue immune cell that stores histamine and releases it when stimulated.", null, "#/physiology/cvs/skin?section=3-the-triple-response-of-lewis", "Skin Circulation §3"],
    'recruitment': ["Recruitment", "Opening of capillaries that were closed or barely perfused, as flow rises. It lowers pulmonary resistance in exercise.", "Distension, the widening of capillaries that were already open.", "#/physiology/cvs/pulmonary?section=2-same-flow-much-lower-pressure", "Pulmonary Circulation §2"],
    'distension': ["Distension", "Widening of pulmonary capillaries that were already open, as pressure and flow rise.", "Recruitment, the opening of closed capillaries.", "#/physiology/cvs/pulmonary?section=2-same-flow-much-lower-pressure", "Pulmonary Circulation §2"],
    'west-zones': ["West zones", "Lung regions defined by comparing alveolar, arterial and venous pressures. They decide whether capillaries are shut, intermittently open or always open.", "Fixed anatomical regions: the zones shift with posture and pressure.", "#/physiology/cvs/pulmonary?section=4-gravity-posture-and-the-lung-s-blood-reservoir", "Pulmonary Circulation §4"],
    'hpv': ["Hypoxic pulmonary vasoconstriction", "Constriction of small pulmonary arteries supplying a poorly oxygenated alveolus, which diverts blood to better-ventilated alveoli.", "Systemic arterioles, which dilate when oxygen is low.", "#/physiology/cvs/pulmonary?section=5-low-oxygen-constricts-lung-vessels", "Pulmonary Circulation §5"],
    'vq-ratio': ["Ventilation–perfusion ratio", "How much air an alveolus receives compared with how much blood. Gas exchange works best when the two are matched.", null, "#/physiology/cvs/pulmonary?section=5-low-oxygen-constricts-lung-vessels", "Pulmonary Circulation §5"],
    'pulmonary-hypertension': ["Pulmonary hypertension", "Abnormally high pressure in the pulmonary arteries, for example from widespread hypoxic constriction. It strains the right ventricle.", "Systemic hypertension, high pressure in the body's arteries.", "#/physiology/cvs/pulmonary?section=5-low-oxygen-constricts-lung-vessels", "Pulmonary Circulation §5"],
    'basal-ganglia': ["Basal ganglia", "Deep groups of neurons that help control movement. With the thalamus and cortex, they are among the parts of the brain most sensitive to low oxygen.", null, "#/physiology/cvs/cerebral?section=1-why-the-brain-can-t-wait-for-blood", "Cerebral Circulation §1"],
    'ketone-bodies': ["Ketone bodies", "Small fuel molecules the liver makes from fat during prolonged starvation. The brain can use them when glucose is scarce.", "Ordinary fatty acids, which the brain uses very little.", "#/physiology/cvs/cerebral?section=1-why-the-brain-can-t-wait-for-blood", "Cerebral Circulation §1"],
    'circle-of-willis': ["Circle of Willis", "A ring of arteries at the base of the brain linking the internal carotid and vertebrobasilar systems. It can sometimes reroute blood if one feeding artery narrows.", "The middle cerebral artery, which branches from it but is not part of the ring.", "#/physiology/cvs/cerebral?section=2-where-does-the-blood-come-from", "Cerebral Circulation §2"],
    'anastomosis': ["Anastomosis", "A connection between two blood vessels that lets blood reach a tissue by more than one route.", null, "#/physiology/cvs/cerebral?section=2-where-does-the-blood-come-from", "Cerebral Circulation §2"],
    'autoregulation': ["Autoregulation", "A tissue's ability to keep its blood flow nearly constant when perfusion pressure changes, by adjusting its arteriolar resistance.", "Hyperaemia, a rise in flow because a tissue needs more.", "#/physiology/cvs/cerebral?section=3-how-does-the-brain-keep-its-blood-flow-steady", "Cerebral Circulation §3"],
    'icp': ["Intracranial pressure (ICP)", "The pressure inside the skull. When it rises, it compresses cerebral vessels and lowers cerebral perfusion pressure.", null, "#/physiology/cvs/cerebral?section=4-a-rigid-box-intracranial-pressure-and-perfusion", "Cerebral Circulation §4"],
    'cpp': ["Cerebral perfusion pressure (CPP)", "The pressure that drives blood through the brain: approximately mean arterial pressure minus intracranial pressure.", "Mean arterial pressure, which can be normal while CPP is low.", "#/physiology/cvs/cerebral?section=4-a-rigid-box-intracranial-pressure-and-perfusion", "Cerebral Circulation §4"],
    'cushing-triad': ["Cushing triad", "Hypertension, bradycardia and irregular breathing caused by severely raised intracranial pressure. A late, dangerous sign.", null, "#/physiology/cvs/cerebral?section=4-a-rigid-box-intracranial-pressure-and-perfusion", "Cerebral Circulation §4"],
    'choroid-plexus': ["Choroid plexus", "Tufts of capillaries covered by specialised epithelium in the ventricles, which make most of the CSF.", null, "#/physiology/cvs/cerebral?section=5-the-coverings-the-ventricles-and-csf", "Cerebral Circulation §5"],
    'arachnoid-villi': ["Arachnoid villi", "Small projections of the arachnoid into the venous sinuses, through which CSF is absorbed into the blood.", null, "#/physiology/cvs/cerebral?section=5-the-coverings-the-ventricles-and-csf", "Cerebral Circulation §5"],
    'hydrocephalus': ["Hydrocephalus", "Build-up of CSF in the ventricles. Non-communicating: the pathway is blocked. Communicating: absorption fails.", null, "#/physiology/cvs/cerebral?section=5-the-coverings-the-ventricles-and-csf", "Cerebral Circulation §5"],
    'bbb': ["Blood–brain barrier", "The seal formed by tight junctions between brain capillary endothelial cells, which tightly controls what passes from blood into brain tissue.", "The blood–CSF barrier, formed by choroid plexus epithelium.", "#/physiology/cvs/cerebral?section=6-the-blood-brain-barrier", "Cerebral Circulation §6"],
    'tight-junctions': ["Tight junctions", "Seals that join neighbouring cells so substances cannot pass between them, only through them.", null, "#/physiology/cvs/cerebral?section=6-the-blood-brain-barrier", "Cerebral Circulation §6"],
    'transmural-pressure': ["Transmural pressure", "The pressure inside a vessel minus the pressure in the tissue around it. It is what stretches the vessel wall.", null, "#/physiology/cvs/local-regulation?section=3-two-mechanisms-myogenic-and-metabolic", "Local Regulation §3"],
    'reactive-hyperaemia': ["Reactive hyperaemia", "A surge of blood flow after a period when flow was cut off. Metabolites that built up during the blockage have dilated the arterioles.", "Active hyperaemia, the extra flow during increased activity.", "#/physiology/cvs/local-regulation?section=4-active-and-reactive-hyperaemia", "Local Regulation §4"],
    'shear-stress': ["Shear stress", "The dragging force of flowing blood on the endothelium. It makes the endothelium release nitric oxide.", null, "#/physiology/cvs/local-regulation?section=5-signals-from-the-endothelium", "Local Regulation §5"],
    'nitric-oxide': ["Nitric oxide (NO)", "A gas released by the endothelium that diffuses into vascular smooth muscle, raises cGMP and relaxes it, dilating the vessel.", null, "#/physiology/cvs/local-regulation?section=5-signals-from-the-endothelium", "Local Regulation §5"],
    'prostacyclin': ["Prostacyclin", "An endothelial signal that dilates vessels and stops platelets clumping.", null, "#/physiology/cvs/local-regulation?section=5-signals-from-the-endothelium", "Local Regulation §5"],
    'endothelin': ["Endothelin-1", "A powerful vasoconstrictor peptide released by the endothelium.", "Nitric oxide, which the endothelium releases to dilate vessels.", "#/physiology/cvs/local-regulation?section=5-signals-from-the-endothelium", "Local Regulation §5"],
    'bradykinin': ["Bradykinin", "A kinin made in plasma and tissues. It dilates arterioles by making the endothelium release nitric oxide, and makes capillaries leakier.", null, "#/physiology/cvs/local-regulation?section=5-signals-from-the-endothelium", "Local Regulation §5"],
    'vasomotor-centre': ["Vasomotor centre", "Groups of neurons in the medulla that control sympathetic outflow to the heart and blood vessels. Its pressor area raises blood pressure; its depressor area inhibits the pressor area.", null, "#/physiology/cvs/neural-humoral?section=2-the-control-centre-in-the-medulla", "Neural and Hormonal Control §2"],
    'nts': ["Nucleus tractus solitarius (NTS)", "The relay station in the medulla that receives signals from baroreceptors and chemoreceptors and adjusts sympathetic and vagal output.", null, "#/physiology/cvs/neural-humoral?section=2-the-control-centre-in-the-medulla", "Neural and Hormonal Control §2"],
    'sympathetic-tone': ["Sympathetic tone", "The constant low-level firing of sympathetic constrictor fibres that keeps arterioles partly constricted. Less firing dilates them.", null, "#/physiology/cvs/neural-humoral?section=3-sympathetic-control-of-the-blood-vessels", "Neural and Hormonal Control §3"],
    'sympathetic-cholinergic': ["Sympathetic cholinergic dilator fibres", "Sympathetic fibres to skeletal muscle that release acetylcholine and dilate its vessels, for example in anticipation of exercise. Their importance in humans is uncertain.", null, "#/physiology/cvs/neural-humoral?section=3-sympathetic-control-of-the-blood-vessels", "Neural and Hormonal Control §3"],
    'atropine': ["Atropine", "A drug that blocks muscarinic acetylcholine receptors. It removes the vagal brake on the SA node, so the heart rate rises.", null, "#/physiology/cvs/neural-humoral?section=4-control-of-the-heart-sympathetic-and-vagus", "Neural and Hormonal Control §4"],
    'angiotensin-ii': ["Angiotensin II", "A hormone formed when the kidney releases renin. It constricts arterioles and triggers aldosterone, thirst and ADH.", null, "#/physiology/cvs/neural-humoral?section=5-hormones-that-act-on-the-circulation", "Neural and Hormonal Control §5"],
    'aldosterone': ["Aldosterone", "An adrenal cortex hormone that makes the kidneys keep sodium, so water follows and blood volume rises over hours to days.", null, "#/physiology/cvs/neural-humoral?section=5-hormones-that-act-on-the-circulation", "Neural and Hormonal Control §5"],
    'adh': ["ADH (vasopressin)", "A posterior pituitary hormone that makes the kidneys keep water. At high levels it also constricts arterioles.", null, "#/physiology/cvs/neural-humoral?section=5-hormones-that-act-on-the-circulation", "Neural and Hormonal Control §5"],
    'anp': ["ANP", "Atrial natriuretic peptide, released when the atria are stretched. It dilates vessels and makes the kidneys lose salt and water.", null, "#/physiology/cvs/neural-humoral?section=5-hormones-that-act-on-the-circulation", "Neural and Hormonal Control §5"],
    'baroreceptors': ["Baroreceptors", "Stretch-sensitive nerve endings in the carotid sinus and aortic arch. They fire faster when blood pressure stretches the arterial wall.", "Chemoreceptors, which sense blood O₂, CO₂ and H⁺.", "#/physiology/cvs/reflexes?section=2-baroreceptors-the-body-s-pressure-sensors", "Reflexes §2"],
    'volume-receptors': ["Volume receptors", "Stretch receptors in the atria and pulmonary vessels. Pressure there depends mainly on how full the circulation is.", null, "#/physiology/cvs/reflexes?section=4-low-pressure-receptors-sensing-how-full-the-circulation-is", "Reflexes §4"],
    'bainbridge': ["Bainbridge reflex", "A rise in heart rate when the atria are stretched by extra volume, helping pump the excess onwards. Weak in humans.", "The baroreflex, which slows the heart when arterial pressure rises.", "#/physiology/cvs/reflexes?section=4-low-pressure-receptors-sensing-how-full-the-circulation-is", "Reflexes §4"],
    'chemoreceptors': ["Peripheral chemoreceptors", "Sensors in the carotid and aortic bodies that detect low O₂, high CO₂ and high H⁺. They mainly drive breathing.", "Baroreceptors, which sense stretch.", "#/physiology/cvs/reflexes?section=5-chemoreceptors", "Reflexes §5"],
    'carotid-body': ["Carotid body", "A small cluster of chemoreceptor cells near the carotid bifurcation that senses blood O₂, CO₂ and H⁺.", "The carotid sinus, the nearby baroreceptor site.", "#/physiology/cvs/reflexes?section=5-chemoreceptors", "Reflexes §5"],
    'vasovagal': ["Vasovagal syncope", "The common faint: a reflex that switches off sympathetic tone and switches on vagal tone, so vessels dilate, the heart slows and cerebral flow drops.", "The normal response to standing, which speeds the heart.", "#/physiology/cvs/gravity?section=4-when-compensation-fails-prolonged-standing-and-fainting", "Gravity §4"],
    'carotid-sinus-syncope': ["Carotid sinus syncope", "Fainting when pressure on a sensitive carotid sinus (a tight collar, turning the head) triggers a strong baroreflex.", null, "#/physiology/cvs/gravity?section=4-when-compensation-fails-prolonged-standing-and-fainting", "Gravity §4"],
    'orthostatic-hypotension': ["Orthostatic hypotension", "A fall in blood pressure on standing of at least 20 mmHg systolic or 10 mmHg diastolic within 3 minutes, because compensation fails.", null, "#/physiology/cvs/gravity?section=5-orthostatic-postural-hypotension", "Gravity §5"],
    'autonomic-neuropathy': ["Autonomic neuropathy", "Damage to autonomic nerves, for example in diabetes. The sympathetic response to standing fails, so blood pressure falls.", null, "#/physiology/cvs/gravity?section=5-orthostatic-postural-hypotension", "Gravity §5"],
    'anti-g-suit': ["Anti-g suit", "A suit that inflates around a pilot's abdomen and legs under high positive g, reducing pooling and keeping venous return up.", null, "#/physiology/cvs/gravity?section=6-acceleration-when-gravity-gets-stronger", "Gravity §6"],
    'shock': ["Shock", "A failure of the circulation to deliver enough blood to keep tissues working normally. It is not defined by one blood pressure value.", null, "#/physiology/cvs/shock?section=1-what-is-shock", "Shock §1"],
    'tamponade': ["Cardiac tamponade", "Fluid in the pericardial sac compressing the heart so it cannot fill: a cause of obstructive shock.", null, "#/physiology/cvs/shock?section=1-what-is-shock", "Shock §1"],
    'tension-pneumothorax': ["Tension pneumothorax", "Air trapped under pressure in the chest, squeezing the great veins and heart: a cause of obstructive shock.", null, "#/physiology/cvs/shock?section=6-the-other-types-of-shock", "Shock §6"],
    'gfr': ["GFR", "Glomerular filtration rate: how much fluid the kidneys filter per minute. It falls when renal arterioles constrict in shock, so urine output falls.", null, "#/physiology/cvs/shock?section=3-what-you-see-and-why", "Shock §3"],
    'anaerobic-glycolysis': ["Anaerobic glycolysis", "Making ATP without oxygen. It produces lactic acid, so underperfused tissues become acidotic.", null, "#/physiology/cvs/shock?section=3-what-you-see-and-why", "Shock §3"],
    'erythropoietin': ["Erythropoietin", "A kidney hormone that drives red cell production. After a bleed, it restores haemoglobin over about 4–5 weeks.", null, "#/physiology/cvs/shock?section=4-how-the-body-fights-back", "Shock §4"],
    'haemoconcentration': ["Haemoconcentration", "A rise in haematocrit and Hb concentration because plasma is lost while red cells stay behind, as in burns.", "The normal Hb seen straight after a bleed, where whole blood is lost.", "#/physiology/cvs/shock?section=6-the-other-types-of-shock", "Shock §6"],
    'myoglobin': ["Myoglobin", "The oxygen-storing protein of muscle. Crushed muscle releases it into the blood, where it can damage the kidneys.", null, "#/physiology/cvs/shock?section=6-the-other-types-of-shock", "Shock §6"],
    'pr-interval': ["PR interval", "On the ECG, the time from the start of the P wave to the start of the QRS complex, normally 0.12–0.20 s. It includes the spread across the atria and the hold-up in the AV node.", "The PR segment, the flat line between the end of the P wave and the QRS.", "#/physiology/cvs/ecg?section=4-waves-segments-and-intervals-what-is-the-difference", "Electrocardiography §4"],
    'pulse-wave': ["Pulse wave", "The ripple of stretch and pressure that runs along the artery walls after each ejection. It travels many times faster than the blood itself.", "Blood flow, the actual movement of blood, which is far slower.", "#/physiology/cvs/pulses?section=1-what-is-an-arterial-pulse", "Pulses and JVP §1"],
    'pulse-pressure': ["Pulse pressure", "Systolic minus diastolic pressure: how far arterial pressure rises with each beat. A bigger stroke volume or a stiffer aorta makes it larger.", "Mean arterial pressure, the average pressure across the whole beat.", "#/physiology/cvs/pulses?section=2-what-do-we-assess-when-palpating-a-pulse", "Pulses and JVP §2"],
    'pulse-deficit': ["Pulse deficit", "When the wrist counts fewer beats than the heart makes. Some beats come so early that the ventricle has barely filled, so they are too weak to reach the wrist.", null, "#/physiology/cvs/pulses?section=2-what-do-we-assess-when-palpating-a-pulse", "Pulses and JVP §2"],
    'jvp': ["JVP (jugular venous pressure/pulse)", "The height and flicker of blood in the internal jugular vein. No valve separates it from the right atrium, so it shows right atrial pressure.", "The carotid pulse, which you can feel and which comes from the left ventricle.", "#/physiology/cvs/pulses?section=3-why-is-the-jugular-venous-pulse-visible-in-the-neck", "Pulses and JVP §3"],
    'sternal-angle': ["Sternal angle (angle of Louis)", "The ridge you can feel where the manubrium meets the body of the sternum, level with the second rib. It sits about 5 cm above the middle of the right atrium.", null, "#/physiology/cvs/pulses?section=6-how-is-the-jvp-estimated-at-the-bedside", "Pulses and JVP §6"],
    'cannon-a-wave': ["Cannon a wave", "A giant a wave: the atrium contracts while the tricuspid valve is shut, so blood is forced back up the neck veins. Seen now and then in complete heart block.", "The giant v wave of tricuspid regurgitation, which comes from the ventricle pushing blood back.", "#/physiology/cvs/pulses?section=7-which-abnormal-jvp-waves-are-most-important", "Pulses and JVP §7"],
    'heart-block': ["Heart block", "A delay or block of the signal at the AV node. First degree: every impulse gets through, but late. Second degree: some are dropped. Third degree: none get through.", null, "#/physiology/cvs/cardiac-conduction?section=8-clinical-significance-of-conduction-disturbances", "Cardiac Conduction §8"],
  });
  window.DOM_GLOSSARY = terms;

  const main = document.getElementById('main');
  if (!main) return;

  const popup = document.createElement('div');
  popup.id = 'dom-glossary-popup';
  popup.className = 'glossary-popup';
  popup.setAttribute('role', 'dialog');
  popup.setAttribute('aria-modal', 'false');
  popup.tabIndex = -1;
  popup.hidden = true;
  document.body.appendChild(popup);
  let active = null;
  let pinned = false;
  let restoring = false;
  const phone = () => window.matchMedia && matchMedia('(max-width: 560px)').matches;

  function place(trigger) {
    if (!trigger || popup.classList.contains('is-sheet')) return;
    // A term that wraps has one box per line: sit above its first line, or below its last.
    const rects = trigger.getClientRects();
    const first = rects[0] || trigger.getBoundingClientRect(), last = rects[rects.length - 1] || first;
    const p = popup.getBoundingClientRect();
    const w = p.width;
    const yAbove = first.top - p.height - 10;
    const r = yAbove >= 8 ? first : last;
    const left = Math.max(10, Math.min(innerWidth - w - 10, r.left + r.width / 2 - w / 2));
    const top = yAbove >= 8 ? yAbove : Math.min(innerHeight - p.height - 8, last.bottom + 10);
    popup.style.left = left + 'px';
    popup.style.top = Math.max(8, top) + 'px';
  }
  function hide(returnFocus = false) {
    const trigger = active;
    if (active) {active.removeAttribute('aria-describedby');active.setAttribute('aria-expanded','false');}
    popup.hidden = true;
    popup.classList.remove('is-sheet');
    active = null;
    pinned = false;
    if (returnFocus && trigger && document.contains(trigger)) {restoring = true; trigger.focus({preventScroll: true}); restoring = false;}
  }
  function show(trigger, stick = false) {
    const entry = terms[trigger?.dataset.glossary];
    if (!entry) return;
    if (active && active !== trigger) {active.removeAttribute('aria-describedby');active.setAttribute('aria-expanded','false');}
    active = trigger; pinned = stick;
    const [name, definition, confuse] = entry; let [, , , href, label] = entry;
    popup.replaceChildren();
    const title = document.createElement('strong');
    title.className = 'gl-title';
    title.id = 'dom-glossary-title';
    title.textContent = name;
    const body = document.createElement('span');
    body.className = 'gl-def';
    body.textContent = definition;
    popup.append(title, body);
    if (confuse) {
      const c = document.createElement('span');
      c.className = 'gl-confuse';
      const b = document.createElement('b');
      b.textContent = "Don't confuse with: ";
      c.append(b, confuse);
      popup.append(c);
    }
    // "Learn it fully" is left out when it would open the section the student is already reading.
    const here = (() => {
      const route = (location.hash.split('?')[0].split('/')[3] || '');
      const article = trigger.closest('.article-text') || document.querySelector('#main .article-text');
      let id = '';
      if (article && trigger.closest('.article-text')) { for (const h of article.querySelectorAll(':scope > h2[id]')) { if (h.compareDocumentPosition(trigger) & Node.DOCUMENT_POSITION_FOLLOWING) id = h.id; } }
      return {route, id};
    })();
    const target = (href || '').match(/cvs\/([a-z0-9-]+)(?:\?section=(.+))?$/);
    if (target && target[1] === here.route && (!target[2] || target[2] === here.id)) href = '';
    if (href) {
      const a = document.createElement('a');
      a.className = 'gl-learn';
      a.href = href;
      a.textContent = 'Learn it fully → ' + (label || '');
      a.addEventListener('click', () => hide());
      popup.append(a);
    }
    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'gl-close';
    close.setAttribute('aria-label', 'Close definition');
    close.textContent = '×';
    close.addEventListener('click', () => hide(true));
    popup.append(close);
    popup.setAttribute('aria-labelledby', title.id);
    popup.classList.toggle('is-sheet', stick && phone());
    popup.hidden = false;
    trigger.setAttribute('aria-describedby', popup.id);
    trigger.setAttribute('aria-expanded', 'true');
    place(trigger);
    if (stick && (href || popup.classList.contains('is-sheet'))) popup.focus({preventScroll: true});
  }
  function enhance() {
    // The marked word stays an inline span (not a <button>) so a multi-word term can wrap across lines
    // and its dotted underline hugs the text. It is made keyboard- and screen-reader-operable here.
    main.querySelectorAll('span[data-term]:not(.glossary-trigger)').forEach(span => {
      if (!terms[span.dataset.term]) return;
      span.classList.add('glossary-trigger');
      span.dataset.glossary = span.dataset.term;
      span.setAttribute('role', 'button');
      span.tabIndex = 0;
      span.setAttribute('aria-label', span.textContent + ', show glossary definition');
      span.setAttribute('aria-expanded','false');
      span.setAttribute('aria-haspopup','dialog');
    });
    if (active && !document.contains(active)) hide();
  }
  const observer = new MutationObserver(enhance);
  observer.observe(main, {childList: true});   // a new page replaces main's children
  enhance();

  main.addEventListener('pointerover', e => {
    if (e.pointerType === 'touch') return;
    const target = e.target.closest?.('.glossary-trigger');
    if (target && !pinned) show(target);
  });
  main.addEventListener('pointerout', e => {
    if (pinned || !active || e.pointerType === 'touch') return;
    if (!active.contains(e.relatedTarget) && !popup.contains(e.relatedTarget)) hide();
  });
  popup.addEventListener('pointerleave', e => {
    if (!pinned && e.pointerType !== 'touch' && !(active && active.contains(e.relatedTarget))) hide();
  });
  main.addEventListener('focusin', e => {
    if (e.target.matches?.('.glossary-trigger') && !pinned && !restoring) show(e.target);
  });
  main.addEventListener('focusout', e => {
    if (active === e.target && !pinned && !popup.contains(e.relatedTarget)) hide();
  });
  main.addEventListener('click', e => {
    const target = e.target.closest?.('.glossary-trigger');
    if (!target) return;
    e.preventDefault();
    if (active === target && pinned) hide();
    else show(target, true);
  });
  main.addEventListener('keydown', e => {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    const target = e.target.closest?.('.glossary-trigger');
    if (!target) return;
    e.preventDefault();
    if (active === target && pinned) hide();
    else show(target, true);
  });
  document.addEventListener('pointerdown', e => {
    if (pinned && active && !active.contains(e.target) && !popup.contains(e.target)) hide();
  });
  document.addEventListener('keydown', e => {if (e.key === 'Escape' && active) hide(popup.contains(document.activeElement));});
  window.addEventListener('scroll', () => {if (active) place(active);}, {passive:true});
  window.addEventListener('resize', () => {if (active) place(active);}, {passive:true});
})();
